    rewardXp: 240,
    completed: true,
    claimed: false,
    icon: 'music_note',
  },
  {
    id: 'quest-2',
    title: 'Crítica de Alta Resolución',
    description: 'Escribe una reseña analizando el rango dinámico y mastering de un álbum.',
    progress: 1,
    target: 1,
    unit: 'reseña',
    reward: '+200 Puntos & Insignia Platinada',
    rewardPts: 200,
    rewardXp: 400,
    completed: true,
    claimed: false,
    icon: 'rate_review',
  },
  {
