          className={`px-4 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all cursor-pointer flex items-center gap-2 ${
            activeTab === 'profile'
              ? 'bg-[#B80C09] text-white shadow-xs'
              : 'bg-gray-100 dark:bg-white/5 text-[#5c435a] dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/10'
          }`}
        >
          <Palette size={16} />
          <span>{ui("Perfil & Avatar Studio")}</span>
        </button>

        <button
          type="button"
          onClick={() => setActiveTab('gear')}
          className={`px-4 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all cursor-pointer flex items-center gap-2 ${
            activeTab === 'gear'
              ? 'bg-[#B80C09] text-white shadow-xs'
              : 'bg-gray-100 dark:bg-white/5 text-[#5c435a] dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/10'
          }`}
        >
          <Headphones size={16} />
          <span>{ui("Equipamiento Audiófilo")}</span>
        </button>

        <button
          type="button"
          onClick={() => setActiveTab('security')}
          className={`px-4 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all cursor-pointer flex items-center gap-2 ${
            activeTab === 'security'
              ? 'bg-[#B80C09] text-white shadow-xs'
              : 'bg-gray-100 dark:bg-white/5 text-[#5c435a] dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/10'
          }`}
        >
          <Lock size={16} />
          <span>{ui("Seguridad & Cifrado")}</span>
        </button>

        <button
          type="button"
          onClick={() => setActiveTab('danger')}
          className={`px-4 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all cursor-pointer flex items-center gap-2 ${
            activeTab === 'danger'
              ? 'bg-rose-600 text-white shadow-xs'
              : 'bg-gray-100 dark:bg-white/5 text-rose-600 dark:text-rose-400 hover:bg-rose-100 dark:hover:bg-rose-950/30'
          }`}
        >
          <Trash2 size={16} />
          <span>{ui("Eliminar Cuenta")}</span>
        </button>
      </div>

      {/* TAB 1: PERFIL & AVATAR STUDIO */}
      {activeTab === 'profile' && (
        <form onSubmit={handleSubmit} className="flex flex-col gap-6">
          <Input
            label={ui("Nombre de Usuario / Firma")}
