          >
            <div className="flex items-center justify-between">
              <span className="material-symbols-outlined text-[#B80C09] dark:text-[#ff4d4a] text-[26px]">pin</span>
              {isSupervisedMode && (
                <span className="text-[10px] font-black uppercase text-[#B80C09] dark:text-[#DCDCDD] bg-[#B80C09]/15 dark:bg-[#B80C09]/30 px-2 py-0.5 rounded-full border border-[#B80C09]/30">{ui("Activo")}</span>
              )}
            </div>
            <div>
              <h4 className="text-sm font-bold text-[#231123] dark:text-[#DCDCDD]">{ui("Supervisado Familiar")}</h4>
              <p className="text-xs text-[#5c435a] dark:text-[#B89CB0] mt-1">{ui("Permite a los padres o tutores autorizar temporalmente canciones mediante su PIN secreto.")}</p>
            </div>
          </div>

          {/* Modo Adulto */}
          <div
            onClick={() => {
              updateParentalControl({ enabled: false, blockExplicit: false, accountType: 'standard' });
              setToastNotice('🔓 Modo Adulto Libre activado (sin restricciones de contenido)');
              setTimeout(() => setToastNotice(''), 3000);
            }}
            className={`p-5 rounded-2xl border-2 transition-all cursor-pointer flex flex-col justify-between gap-3 ${
              isFreeAdultMode
                ? 'border-[#003844] dark:border-[#52a2b0] bg-[#003844]/10 dark:bg-[#003844]/30 shadow-md ring-2 ring-[#003844]/40'
                : 'border-gray-200 dark:border-white/10 bg-gray-50/70 dark:bg-black/20 hover:border-[#003844]/40'
            }`}
          >
            <div className="flex items-center justify-between">
              <span className="material-symbols-outlined text-[#003844] dark:text-[#52a2b0] text-[26px]">lock_open</span>
              {isFreeAdultMode && (
                <span className="text-[10px] font-black uppercase text-[#003844] dark:text-[#DCDCDD] bg-[#003844]/15 dark:bg-[#003844]/50 px-2 py-0.5 rounded-full border border-[#003844]/30">{ui("Activo")}</span>
              )}
            </div>
            <div>
              <h4 className="text-sm font-bold text-[#231123] dark:text-[#DCDCDD]">{ui("Modo Libre (Adultos)")}</h4>
              <p className="text-xs text-[#5c435a] dark:text-[#B89CB0] mt-1">{ui("Acceso sin restricciones a todo el catálogo discográfico, letras y podcasts de la plataforma.")}</p>
            </div>
          </div>
        </div>
      </div>

      {/* 2. TEMPORIZADOR DE ESTUDIO POMODORO & AMBIENTES PARA NIÑOS */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Temporizador de Tareas & Pomodoro Kids */}
        <div className="p-6 rounded-3xl bg-gradient-to-br from-[#231123] to-[#3a1b33] text-white border border-white/15 shadow-md flex flex-col justify-between gap-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2.5">
              <span className="material-symbols-outlined text-[24px] text-amber-400">timer</span>
              <div>
                <h4 className="text-base font-bold text-white">{ui("Temporizador de Estudio Kids (Pomodoro)")}</h4>
                <p className="text-xs text-pink-200/70">{ui("Sesión enfocada de 25 min para hacer tareas sin pantallas.")}</p>
              </div>
            </div>
          </div>

          <div className="flex flex-col items-center justify-center p-5 rounded-2xl bg-black/40 border border-white/10">
            <span className="text-4xl sm:text-5xl font-mono font-black text-amber-300 tracking-wider">
              {formatTime(pomodoroSeconds)}
            </span>
            <span className="text-xs text-white/70 mt-1">
              {isPomodoroRunning ? ui("🎧 Sesión en curso con música suave") : ui("Listo para iniciar")}
            </span>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setIsPomodoroRunning(!isPomodoroRunning)}
              className={`flex-1 py-2.5 rounded-xl font-bold text-xs uppercase tracking-wider transition-all flex items-center justify-center gap-1.5 cursor-pointer shadow-md ${
                isPomodoroRunning ? 'bg-amber-500 hover:bg-amber-600 text-white' : 'bg-emerald-600 hover:bg-emerald-500 text-white'
              }`}
            >
              <span className="material-symbols-outlined text-[18px]">
                {isPomodoroRunning ? 'pause' : 'play_arrow'}
              </span>
              <span>{isPomodoroRunning ? ui("Pausar Estudio") : ui("Iniciar Tiempo de Tareas (25 min)")}</span>
            </button>
            <button
              type="button"
              onClick={() => {
                setIsPomodoroRunning(false);
                setPomodoroSeconds(25 * 60);
              }}
              className="px-3.5 py-2.5 rounded-xl bg-white/10 hover:bg-white/20 text-white font-bold text-xs cursor-pointer"
              title={ui("Reiniciar a 25 min")}
            >
              <span className="material-symbols-outlined text-[16px]">restart_alt</span>
            </button>
          </div>
        </div>

        {/* Sonidos Calmantes & Ruido Blanco para Dormir */}
        <div className="p-6 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-xs flex flex-col justify-between gap-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2.5">
              <span className="material-symbols-outlined text-[24px] text-teal-500">spa</span>
              <div>
                <h4 className="text-base font-bold text-[#231123] dark:text-white">{ui("Sonidos Calmantes & Naturaleza")}</h4>
                <p className="text-xs text-[#5c435a] dark:text-[#B89CB0]">{ui("Ambientes sonoros para relajar y dormir.")}</p>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-2">
            {AMBIENT_SOUNDS.map((sound) => {
              const isActive = activeAmbient === sound.id;
              return (
                <button
                  key={sound.id}
                  type="button"
                  onClick={() => {
                    setActiveAmbient(isActive ? null : sound.id);
                    setToastNotice(isActive ? 'Sonido ambiental detenido' : `Reproduciendo: ${sound.name}`);
                  }}
                  className={`p-3 rounded-xl border text-left transition-all cursor-pointer flex flex-col justify-between gap-1 ${
                    isActive
                      ? 'bg-teal-600 text-white border-teal-600 shadow-md ring-2 ring-teal-400/40'
                      : 'bg-gray-50 dark:bg-black/20 border-gray-200 dark:border-white/10 hover:border-teal-500'
                  }`}
                >
                  <span className="text-xs font-bold truncate">{sound.name}</span>
                  <span className={`text-[10px] ${isActive ? 'text-teal-100' : 'text-gray-400'}`}>
                    {sound.desc}
                  </span>
                </button>
              );
            })}
          </div>

          <div className="flex items-center justify-between text-xs text-teal-600 dark:text-teal-400 font-semibold pt-1">
            <span>{activeAmbient ? ui("🔊 Reproducción ambiental activa") : ui("Toca para activar ambiente")}</span>
            {activeAmbient && (
              <button
                type="button"
                onClick={() => setActiveAmbient(null)}
                className="text-[11px] underline text-gray-500 hover:text-red-500 cursor-pointer"
              >{ui("Detener todo")}</button>
            )}
          </div>
        </div>
      </div>

      {/* 3. TRIVIA MUSICAL EDUCATIVA PARA NIÑOS */}
      <div className="p-6 sm:p-8 rounded-3xl bg-gradient-to-r from-amber-500/15 via-[#4B2840]/30 to-purple-900/20 border border-amber-300/40 dark:border-white/10 shadow-xs flex flex-col gap-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <span className="material-symbols-outlined text-[24px] text-amber-500">quiz</span>
            <div>
              <h4 className="text-base font-bold text-[#231123] dark:text-white">{ui("Trivia Musical Kids & Juegos de Oído")}</h4>
              <p className="text-xs text-[#5c435a] dark:text-[#B89CB0]">{ui("Aprende sobre instrumentos e historia musical mientras escuchas.")}</p>
            </div>
          </div>
          <span className="text-xs font-bold text-amber-600 dark:text-amber-400 bg-amber-100 dark:bg-amber-950/60 px-3 py-1 rounded-full border border-amber-300/30">{ui("Puntos:")} {quizScore}
          </span>
        </div>

        <div className="p-5 rounded-2xl bg-white dark:bg-black/40 border border-[#e6d5e2] dark:border-white/10 flex flex-col gap-3">
          <p className="text-sm font-bold text-[#231123] dark:text-white">
            {currentQuiz.question}
          </p>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
            {currentQuiz.options.map((opt, idx) => {
              const isSelected = quizSelected === idx;
              const isCorrect = idx === currentQuiz.correct;

              return (
                <button
                  key={opt}
                  type="button"
                  onClick={() => handleAnswerQuiz(idx)}
                  disabled={quizSelected !== null}
                  className={`p-3 rounded-xl border text-xs font-bold transition-all cursor-pointer ${
                    quizSelected === null
                      ? 'bg-gray-50 dark:bg-white/5 border-gray-200 dark:border-white/10 hover:border-amber-500 hover:bg-amber-50 dark:hover:bg-white/10'
                      : isSelected && isCorrect
                      ? 'bg-emerald-600 text-white border-emerald-600 shadow-md'
                      : isSelected && !isCorrect
                      ? 'bg-red-600 text-white border-red-600'
                      : isCorrect
                      ? 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border-emerald-500'
                      : 'opacity-50'
                  }`}
                >
                  {opt}
                </button>
              );
            })}
          </div>

          {quizSelected !== null && (
            <div className="pt-2 flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs">
              <span className="text-emerald-600 dark:text-emerald-400 font-semibold">
                {currentQuiz.fact}
              </span>
              <button
                type="button"
                onClick={handleNextQuiz}
                className="px-4 py-1.5 rounded-xl bg-amber-500 hover:bg-amber-600 text-white font-bold text-xs self-start sm:self-auto cursor-pointer"
              >{ui("Siguiente Pregunta ➔")}</button>
            </div>
          )}
        </div>
      </div>

      {/* 4. CANALES DE DESCUBRIMIENTO EXCLUSIVOS "SONAR KIDS" */}
      <div className="p-6 sm:p-8 rounded-3xl bg-gradient-to-br from-[#231123] via-[#3d1a35] to-[#003844] text-white border border-white/15 shadow-xl flex flex-col gap-5">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-amber-500 text-white shadow-md">
              <span className="material-symbols-outlined text-[24px]">explore</span>
            </div>
            <div>
              <h3 className="text-lg font-black tracking-tight">{ui("Canales de Música Segura & Educativa \"Sonar Kids\"")}</h3>
              <p className="text-xs text-pink-200/80">{ui("Selecciones curadas para fomentar la creatividad, el estudio y el descanso.")}</p>
            </div>
          </div>
          <span className="text-[11px] font-bold text-emerald-300 bg-emerald-950/60 px-3 py-1 rounded-xl border border-emerald-500/30 self-start sm:self-auto">{ui("100% Sin Contenido Explícito")}</span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {KIDS_CHANNELS.map((ch) => (
            <motion.div
              key={ch.id}
              whileHover={{ y: -3 }}
              className="p-4 rounded-2xl bg-black/40 border border-white/10 flex flex-col justify-between gap-3 group hover:border-amber-400 transition-all"
            >
              <div className="flex items-center gap-3">
                <div className={`p-2.5 rounded-xl bg-gradient-to-tr ${ch.color} text-white shadow-md`}>
                  <span className="material-symbols-outlined text-[20px]">{ch.icon}</span>
                </div>
                <div>
                  <h4 className="text-sm font-bold text-white group-hover:text-amber-300 transition-colors">
                    {ch.title}
                  </h4>
                </div>
              </div>

              <p className="text-xs text-pink-200/70 leading-relaxed">
                {ch.description}
              </p>

              <button
                type="button"
                onClick={() => playTrack(ch.sampleTrack)}
                className="w-full py-2 px-3 rounded-xl bg-white/10 hover:bg-white text-white hover:text-[#231123] text-xs font-bold transition-all flex items-center justify-center gap-1.5 cursor-pointer shadow-xs"
              >
                <span className="material-symbols-outlined text-[16px]">play_arrow</span>
                <span>{ui("Reproducir Canal")}</span>
              </button>
            </motion.div>
          ))}
        </div>

        {/* JUKEBOX SEGURO DE 1 TAP */}
        <div className="pt-4 border-t border-white/10 flex flex-col gap-3">
          <div className="flex items-center justify-between">
            <span className="text-xs font-extrabold uppercase tracking-wider text-amber-400 flex items-center gap-1.5">
              <span className="material-symbols-outlined text-[16px]">music_note</span>
              <span>{ui("Jukebox Sonar Kids · Éxitos 100% Seguros (1-Tap Play)")}</span>
            </span>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2.5">
            {KIDS_SAFE_JUKEBOX.map((track) => (
              <div
                key={track.id}
                onClick={() => playTrack(track)}
                className="p-3 rounded-xl bg-white/5 hover:bg-white/15 border border-white/10 flex items-center justify-between gap-3 cursor-pointer transition-all hover:border-amber-400/50"
              >
                <div className="flex items-center gap-2.5 min-w-0">
                  <img
                    src={track.cover}
                    alt={track.title}
                    className="w-10 h-10 rounded-lg object-cover shadow-xs shrink-0"
                  />
                  <div className="flex flex-col min-w-0">
                    <span className="text-xs font-bold text-white truncate">{track.title}</span>
                    <span className="text-[10px] text-pink-200/70 truncate">{track.artist}</span>
                  </div>
                </div>
                <div className="flex items-center gap-1.5 shrink-0">
                  <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-300 border border-amber-400/30">
                    {track.tag}
                  </span>
                  <div className="w-7 h-7 rounded-full bg-amber-500 hover:bg-amber-400 text-white flex items-center justify-center shadow-xs">
                    <span className="material-symbols-outlined text-[14px]">play_arrow</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* 5. LÍMITE DE TIEMPO DIARIO & CUIDADO AUDITIVO */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Límite de Tiempo de Escucha Diario */}
        <div className="p-6 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-xs flex flex-col justify-between gap-5">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2.5">
              <span className="material-symbols-outlined text-[24px] text-amber-500">hourglass_top</span>
              <div>
                <h4 className="text-base font-bold text-[#231123] dark:text-white">{ui("Límite de Tiempo Diario")}</h4>
                <p className="text-xs text-[#5c435a] dark:text-[#B89CB0]">{ui("Evita la fatiga auditiva limitando las horas de reproducción al día.")}</p>
              </div>
            </div>
          </div>

          <div className="p-4 rounded-2xl bg-gray-50 dark:bg-black/30 border border-[#e6d5e2] dark:border-white/10 flex flex-col gap-2">
            <div className="flex justify-between items-baseline text-xs font-bold">
              <span className="text-[#5c435a] dark:text-pink-200">{ui("Uso hoy:")} {parentalSettings.listenedTodayMinutes} min
              </span>
              <span className="text-[#B80C09] dark:text-pink-300 font-mono">{ui("Límite:")} {parentalSettings.dailyLimitMinutes} min ({usagePercent}%)
              </span>
            </div>

            <div className="w-full h-3 bg-gray-200 dark:bg-white/10 rounded-full overflow-hidden p-0.5">
              <motion.div
                initial={{ width: 0 }}
                animate={{ width: `${usagePercent}%` }}
                className={`h-full rounded-full ${
                  usagePercent > 85
                    ? 'bg-[#B80C09]'
                    : usagePercent > 50
                    ? 'bg-amber-500'
                    : 'bg-emerald-500'
                }`}
              />
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <span className="text-xs font-bold text-gray-500">{ui("Ajustar a:")}</span>
            {[30, 45, 60, 90, 120].map((mins) => (
              <button
                key={mins}
                type="button"
                onClick={() => handleSaveSettings({ dailyLimitMinutes: mins })}
                className={`px-3 py-1 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                  parentalSettings.dailyLimitMinutes === mins
                    ? 'bg-[#B80C09] text-white shadow-xs'
                    : 'bg-gray-100 dark:bg-white/10 text-gray-700 dark:text-gray-200 hover:bg-gray-200'
                }`}
              >
                {mins} min
              </button>
            ))}
          </div>
        </div>

        {/* Protección Auditiva & Limitador de Decibeles */}
        <div className="p-6 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-xs flex flex-col justify-between gap-5">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2.5">
              <span className="material-symbols-outlined text-[24px] text-teal-500">hearing</span>
              <div>
                <h4 className="text-base font-bold text-[#231123] dark:text-white">{ui("Protección de Oído & Volumen Seguro")}</h4>
                <p className="text-xs text-[#5c435a] dark:text-[#B89CB0]">{ui("Cumple con el estándar de seguridad auditiva de la OMS para niños.")}</p>
              </div>
            </div>
          </div>

          <div className="p-4 rounded-2xl bg-gray-50 dark:bg-black/30 border border-[#e6d5e2] dark:border-white/10 flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <div>
                <span className="text-xs font-bold text-[#231123] dark:text-white block">{ui("Tope Máximo de Volumen (")}{parentalSettings.maxDecibels} dB)
                </span>
                <span className="text-[11px] text-gray-500 dark:text-gray-400">{ui("Previene aumentos repentinos o picos de volumen peligrosos.")}</span>
              </div>
              <button
                type="button"
                onClick={() => handleSaveSettings({ volumeCapEnabled: !parentalSettings.volumeCapEnabled })}
                className={`w-12 h-6 rounded-full transition-colors relative cursor-pointer ${
                  parentalSettings.volumeCapEnabled ? 'bg-emerald-500' : 'bg-gray-300 dark:bg-gray-600'
                }`}
              >
                <div
                  className={`w-5 h-5 rounded-full bg-white shadow-md absolute top-0.5 transition-transform ${
                    parentalSettings.volumeCapEnabled ? 'translate-x-6' : 'translate-x-1'
                  }`}
                />
              </button>
            </div>

            <div className="flex items-center gap-2 pt-2 border-t border-gray-200 dark:border-white/10">
              <span className="text-xs font-bold text-gray-500">{ui("Nivel Máximo:")}</span>
              {[70, 75, 80, 85].map((db) => (
                <button
                  key={db}
                  type="button"
                  onClick={() => handleSaveSettings({ maxDecibels: db })}
                  className={`px-3 py-1 rounded-xl text-xs font-mono font-bold transition-all cursor-pointer ${
                    parentalSettings.maxDecibels === db
                      ? 'bg-teal-600 text-white shadow-xs'
                      : 'bg-gray-100 dark:bg-white/10 text-gray-700 dark:text-gray-200'
                  }`}
                >
                  {db} dB
                </button>
              ))}
            </div>
          </div>

          <div className="flex items-center gap-2 text-xs text-emerald-600 dark:text-emerald-400 font-semibold">
            <span className="material-symbols-outlined text-[16px]">verified</span>
            <span>{ui("Estándar de audición segura activo en todos los reproductores")}</span>
          </div>
        </div>
      </div>

      {/* 6. PIN DE AUTORIZACIÓN & FILTRO DE PALABRAS CLAVE */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* PIN de Autorización */}
        <div className="p-6 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-xs flex flex-col justify-between gap-4">
          <div>
            <h4 className="text-base font-bold text-[#231123] dark:text-white flex items-center gap-2">
              <span className="material-symbols-outlined text-[20px] text-[#B80C09]">key</span>
              <span>{ui("PIN de Autorización Parental")}</span>
            </h4>
            <p className="text-xs text-[#5c435a] dark:text-[#B89CB0] mt-1">{ui("Código de 4 dígitos que los padres usan para autorizar música o cambiar ajustes de seguridad.")}</p>
          </div>

          <form onSubmit={handleSavePin} className="flex items-center gap-3">
            <input
              type="password"
              maxLength={4}
              value={pinInput}
              onChange={(e) => setPinInput(e.target.value.replace(/\D/g, '').slice(0, 4))}
              placeholder="1234"
              className="w-28 text-center tracking-[0.4em] font-mono text-base py-2.5 px-3 rounded-xl bg-gray-50 dark:bg-black/30 border border-gray-300 dark:border-white/20 text-[#231123] dark:text-white font-black focus:outline-hidden focus:border-[#B80C09]"
            />
            <button
              type="submit"
              disabled={pinInput.trim().length !== 4}
              className="px-5 py-2.5 rounded-xl bg-[#B80C09] hover:bg-[#960a07] text-white text-xs font-bold transition-all disabled:opacity-50 cursor-pointer shadow-xs"
            >{ui("Guardar PIN")}</button>
          </form>

          <div className="pt-3 border-t border-gray-100 dark:border-white/10 flex items-center justify-between">
            <span className="text-xs text-[#5c435a] dark:text-[#B89CB0]">{ui("Simulación de Bloqueo:")}</span>
            <button
              type="button"
              onClick={() => {
                playTrack({
                  id: 9896728,
                  title: 'To Pimp A Butterfly (Muestra Explícita)',
                  artist: 'Kendrick Lamar',
                  album: 'To Pimp A Butterfly',
                  explicit: true,
                  explicit_lyrics: true,
                });
              }}
              className="px-3 py-1.5 rounded-xl bg-gray-100 hover:bg-gray-200 dark:bg-white/10 dark:hover:bg-white/20 text-xs font-bold text-[#231123] dark:text-white transition-all flex items-center gap-1 cursor-pointer"
            >
              <span className="material-symbols-outlined text-[15px] text-[#B80C09]">lock</span>
              <span>{ui("Probar PIN en Reproductor")}</span>
            </button>
          </div>
        </div>

        {/* Lista Negra de Palabras Clave o Artistas */}
        <div className="p-6 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-xs flex flex-col justify-between gap-4">
          <div>
            <h4 className="text-base font-bold text-[#231123] dark:text-white flex items-center gap-2">
              <span className="material-symbols-outlined text-[20px] text-[#B80C09]">block</span>
              <span>{ui("Palabras & Artistas Restringidos")}</span>
            </h4>
            <p className="text-xs text-[#5c435a] dark:text-[#B89CB0] mt-1">{ui("Agrega términos que se filtrarán automáticamente del buscador y recomendaciones para niños.")}</p>
          </div>

          <form onSubmit={handleAddBlockedKeyword} className="flex items-center gap-2">
            <input
              type="text"
              value={newKeyword}
              onChange={(e) => setNewKeyword(e.target.value)}
              placeholder={ui("Ej. Artista, palabra o tema...")}
              className="flex-1 text-xs py-2 px-3 rounded-xl bg-gray-50 dark:bg-black/30 border border-gray-300 dark:border-white/20 text-[#231123] dark:text-white focus:outline-hidden focus:border-[#B80C09]"
            />
            <button
              type="submit"
              disabled={!newKeyword.trim()}
              className="px-4 py-2 rounded-xl bg-[#231123] dark:bg-white text-white dark:text-[#231123] text-xs font-bold transition-all disabled:opacity-50 cursor-pointer"
            >{ui("+ Bloquear")}</button>
          </form>

          <div className="flex flex-wrap gap-1.5 max-h-24 overflow-y-auto">
            {parentalSettings.blockedKeywords.map((kw) => (
              <span
                key={kw}
                className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-red-50 dark:bg-red-950/40 text-red-700 dark:text-red-300 text-xs font-semibold border border-red-200 dark:border-red-900/30"
              >
                <span>{kw}</span>
                <button
                  type="button"
                  onClick={() => handleRemoveKeyword(kw)}
                  className="hover:text-red-900 dark:hover:text-white cursor-pointer ml-0.5"
                >
                  ×
                </button>
              </span>
            ))}
          </div>
        </div>
      </div>

      {/* 7. REGISTRO DE ACTIVIDAD Y AUDITORÍA PARENTAL */}
      <div className="p-6 sm:p-8 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-xs flex flex-col gap-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <span className="material-symbols-outlined text-[22px] text-[#5c435a] dark:text-[#B89CB0]">
              history_toggle_off
            </span>
            <h4 className="text-base font-bold text-[#231123] dark:text-white">{ui("Historial de Actividad & Auditoría de Seguridad Kids")}</h4>
          </div>
          <span className="text-xs text-gray-500 font-mono">{ui("Últimas 24 horas")}</span>
        </div>

        <div className="flex flex-col divide-y divide-gray-100 dark:divide-white/10 text-xs">
          {activityLogs.map((log) => (
            <div key={log.id} className="py-2.5 flex items-center justify-between gap-4">
              <div className="flex items-center gap-2.5">
                <span
                  className={`w-2 h-2 rounded-full ${
                    log.safe ? 'bg-emerald-500' : 'bg-[#B80C09] animate-pulse'
                  }`}
                />
                <div>
                  <span className="font-bold text-[#231123] dark:text-white">{log.track}</span>
                  <span className="text-gray-400 block text-[11px]">{log.action}</span>
                </div>
              </div>
              <span className="text-gray-400 font-mono text-[11px] shrink-0">{log.time}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default EnhancedParentalControl;

import { useUIText } from '../../../shared/i18n/use-ui-text.js';
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const MOOD_TAGS = [
  '☕ Café & Lluvia',
  '🌙 Madrugada Hi-Fi',
  '⚡ Concentración Profunda',
  '🍷 Relax de Fin de Semana',
  '🎧 Análisis Técnico 180g',
];

export const ListeningJournalModal = ({ album, isOpen, onClose }) => {
  const ui = useUIText();
  const [entries, setEntries] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem('sonar_listening_journal') || '{}');
    } catch {
      return {};
    }
  });

  const albumId = album?.id || 'general';
  const currentNote = entries[albumId] || { text: '', mood: MOOD_TAGS[0], timestampMark: '03:15' };

  const [noteText, setNoteText] = useState(currentNote.text);
  const [selectedMood, setSelectedMood] = useState(currentNote.mood);
  const [timestampMark, setTimestampMark] = useState(currentNote.timestampMark);
  const [isSaved, setIsSaved] = useState(false);

  const handleSave = (e) => {
    e?.preventDefault();
    const updated = {
      ...entries,
      [albumId]: {
        albumTitle: album?.title,
        artist: album?.artist,
        text: noteText,
        mood: selectedMood,
        timestampMark,
        date: new Date().toLocaleDateString(),
      },
    };
    setEntries(updated);
    try {
      localStorage.setItem('sonar_listening_journal', JSON.stringify(updated));
    } catch {}
    setIsSaved(true);
    setTimeout(() => {
      setIsSaved(false);
      onClose && onClose();
    }, 1200);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-md">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="w-full max-w-lg p-6 sm:p-8 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/15 shadow-2xl text-[#231123] dark:text-white flex flex-col gap-5 relative"
      >
        <button
          type="button"
          onClick={onClose}
          className="absolute top-5 right-5 p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/10 text-gray-400 hover:text-gray-700 dark:hover:text-white transition-colors cursor-pointer"
        >
          <span className="material-symbols-outlined text-[20px]">close</span>
        </button>

        <div className="flex items-center gap-3">
          <div className="p-3 rounded-2xl bg-[#B80C09]/20 text-[#B80C09]">
            <span className="material-symbols-outlined text-[24px]">edit_note</span>
          </div>
          <div>
            <span className="text-[11px] font-bold uppercase tracking-wider text-[#B80C09]">{ui("Diario Acústico & Sleeve Notes")}</span>
            <h3 className="text-lg font-black tracking-tight">{album?.title || ui("Reflexión Musical")}</h3>
          </div>
        </div>

        <form onSubmit={handleSave} className="flex flex-col gap-4">
          {/* Selector de Ambiente / Estado de Ánimo */}
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold text-[#5c435a] dark:text-pink-200">{ui("Atmósfera de Audición:")}</label>
            <div className="flex flex-wrap gap-2">
              {MOOD_TAGS.map((tag) => (
                <button
                  key={tag}
                  type="button"
                  onClick={() => setSelectedMood(tag)}
                  className={`text-xs font-semibold px-3 py-1.5 rounded-xl border transition-all cursor-pointer ${
                    selectedMood === tag
                      ? 'bg-[#B80C09] text-white border-[#B80C09] shadow-sm'
                      : 'bg-gray-50 dark:bg-black/20 border-gray-200 dark:border-white/10 text-[#5c435a] dark:text-[#DCDCDD]'
                  }`}
                >
                  {tag}
                </button>
              ))}
            </div>
          </div>

          {/* Marcador de Timestamp */}
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold text-[#5c435a] dark:text-pink-200">{ui("Momento o Pasaje Destacado (mm:ss):")}</label>
            <input
              type="text"
              value={timestampMark}
              onChange={(e) => setTimestampMark(e.target.value)}
              placeholder="03:45 (Solo de sintetizador / Entrada de batería)"
              className="w-full text-xs font-medium py-2.5 px-3 rounded-xl bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 focus:outline-hidden focus:border-[#B80C09]"
            />
          </div>

          {/* Área de Texto / Notas Íntimas */}
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold text-[#5c435a] dark:text-pink-200">{ui("Tus Notas de Escucha Privadas:")}</label>
            <textarea
              rows={4}
              value={noteText}
              onChange={(e) => setNoteText(e.target.value)}
              placeholder="¿Qué sensaciones te provocó la textura sonora, el rango dinámico o la mezcla espacial de este álbum?"
              className="w-full text-xs leading-relaxed py-2.5 px-3 rounded-xl bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 focus:outline-hidden focus:border-[#B80C09]"
            />
          </div>

          <button
            type="submit"
            className="w-full py-3 rounded-xl bg-[#B80C09] hover:bg-[#960a07] text-white text-xs font-black tracking-wider uppercase transition-all shadow-md cursor-pointer mt-1"
          >
            {isSaved ? ui("¡Nota Guardada en tu Diario!") : ui("Guardar en Diario de Escucha")}
          </button>
        </form>
      </motion.div>
    </div>
  );
};

export default ListeningJournalModal;

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Avatar } from '../../../shared/components/ui/avatar';
import { useRouter } from '../../../shared/routing/app-router';
import { socialService } from '../../../shared/services/social-service';
import { useAuth } from '../../../shared/context/auth-context';
import { useLanguage } from '../../../shared/context/language-context';

export const ProfileHeader = ({
  user,
  actualReviewsCount,
  onEditProfile,
  isVisitor = false,
}) => {
  const router = useRouter?.();
  const { user: authUser } = useAuth();
  const { t } = useLanguage();

  const currentUser = user || {
    name: 'Mateo Rivaes',
    username: '@mateorivaes',
    bio: 'Coleccionista de vinilos de jazz y art-rock de los 70 y 2000s. Siempre en busca de la masterización perfecta.',
    avatarUrl: '',
    bannerUrl: '',
    preferences: ['Art Rock', 'Electrónica'],
  };

  const currentAuthId = authUser?.id || 'guest_user';
  const targetId = currentUser?.id || currentUser?.username || 'user';
  const isOwnProfile = !isVisitor && (String(currentAuthId) === String(targetId) || !user);

  const [isFollowing, setIsFollowing] = useState(() =>
    socialService.isFollowingUser(currentAuthId, targetId)
  );

  const [equippedFrame, setEquippedFrame] = useState(() => {
    try {
      return localStorage.getItem('sonar_equipped_frame') || currentUser?.equippedFrame || '';
    } catch {
      return '';
    }
  });

  const [equippedTitle, setEquippedTitle] = useState(() => {
    try {
      return localStorage.getItem('sonar_equipped_title') || currentUser?.equippedTitle || '';
    } catch {
      return '';
    }
  });

  const [userPoints, setUserPoints] = useState(() => {
    try {
      return Number(localStorage.getItem('sonar_user_points') || currentUser?.sonarPoints || 1250);
    } catch {
      return 1250;
    }
  });

  useEffect(() => {
    setIsFollowing(socialService.isFollowingUser(currentAuthId, targetId));
    const handleFollowChange = (e) => {
      if (e.detail?.targetUserId === String(targetId)) {
        setIsFollowing(e.detail.isFollowing);
      }
    };
    const handleCustomizationChange = (e) => {
      if (e.detail?.equippedFrame !== undefined) setEquippedFrame(e.detail.equippedFrame);
      if (e.detail?.equippedTitle !== undefined) setEquippedTitle(e.detail.equippedTitle);
    };
    window.addEventListener('sonar:follow-user-changed', handleFollowChange);
    window.addEventListener('sonar:profile-customization-changed', handleCustomizationChange);
    return () => {
      window.removeEventListener('sonar:follow-user-changed', handleFollowChange);
      window.removeEventListener('sonar:profile-customization-changed', handleCustomizationChange);
    };
  }, [currentAuthId, targetId]);

  const handleToggleFollow = () => {
    const nextState = socialService.toggleFollowUser(currentAuthId, targetId, currentUser);
    setIsFollowing(nextState);
  };

  const { displayName, handle } = socialService.formatUserIdentity(currentUser);
  const stats = socialService.getUserStats(currentUser, actualReviewsCount);
  const bio = currentUser.bio || t('profile.default_bio', 'Nuevo melómano explorando vinilos y texturas acústicas en Sonar.');

  const handleEditClick = () => {
    try {
      sessionStorage.setItem('sonar_profile_settings_tab', 'profile');
    } catch {}
    if (onEditProfile) {
      onEditProfile();
    } else if (router?.navigate) {
      router.navigate('profile-settings');
    } else {
      window.location.hash = '#profile-settings';
    }
  };

  const defaultBannerGradient = 'linear-gradient(135deg, rgba(184, 12, 9, 0.7) 0%, rgba(75, 40, 64, 0.95) 100%)';
  const bannerBackground = currentUser.bannerUrl
    ? `url(${currentUser.bannerUrl}) center/cover no-repeat`
    : currentUser.bannerGradient || defaultBannerGradient;

  const frameClass = {
    'frame-gold-vinyl': 'ring-4 ring-amber-400 shadow-[0_0_25px_rgba(251,191,36,0.8)]',
    'frame-neon-cyber': 'ring-4 ring-cyan-400 shadow-[0_0_25px_rgba(6,182,212,0.85)]',
    'frame-valve-tube': 'ring-4 ring-orange-500 shadow-[0_0_20px_rgba(249,115,22,0.75)]',
    'frame-hologram': 'ring-4 ring-purple-400 shadow-[0_0_26px_rgba(168,85,247,0.8)]',
    'frame-prism-rainbow': 'ring-4 ring-pink-500 shadow-[0_0_26px_rgba(236,72,153,0.85)]',
    'frame-analog-wood': 'ring-4 ring-amber-700 shadow-[0_0_20px_rgba(180,83,9,0.75)]',
  }[equippedFrame] || 'ring-4 ring-white dark:ring-[#4B2840] shadow-xl';

  return (
    <motion.section
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: 'easeOut' }}
      className="w-full rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-[0_10px_35px_-5px_rgba(75,40,64,0.06)] dark:shadow-[0_12px_40px_-8px_rgba(0,0,0,0.5)] transition-colors duration-300 relative overflow-hidden"
    >
      {/* Banner Superior Personalizado / Decorativo */}
      <div
        className="w-full h-32 sm:h-44 relative overflow-hidden transition-all duration-300"
        style={{ background: bannerBackground }}
      >
        <div className="absolute inset-0 bg-black/20 backdrop-blur-[2px]" />
        {isOwnProfile && (
          <button
            type="button"
            onClick={handleEditClick}
            className="absolute top-3 right-3 px-3 py-1.5 rounded-xl bg-black/50 hover:bg-black/70 text-white text-xs font-semibold backdrop-blur-md border border-white/20 transition-all flex items-center gap-1.5 cursor-pointer shadow-sm"
          >
            <span className="material-symbols-outlined text-[15px]">photo_camera</span>
            <span>{t('profile.change_cover', 'Cambiar Portada')}</span>
          </button>
        )}
      </div>

      {/* Contenido del Perfil */}
      <div className="p-6 sm:p-8 pt-0 sm:pt-0 relative z-10 -mt-12 sm:-mt-16">
        <div className="flex flex-col md:flex-row items-center md:items-start justify-between gap-6 sm:gap-8">
          {/* Lado Izquierdo: Avatar y Datos */}
          <div className="flex flex-col sm:flex-row items-center sm:items-start gap-5 sm:gap-6 text-center sm:text-left flex-1">
            {/* Avatar con borde flotante y Marco de Boutique */}
            <div className={`shrink-0 rounded-full bg-white dark:bg-[#231123] transition-all duration-300 ${frameClass}`}>
              <Avatar
                src={currentUser.avatarUrl}
                name={displayName}
                avatarBg={currentUser.avatarBg || currentUser.avatarColor}
                avatarHue={currentUser.avatarHue}
                avatarTone={currentUser.avatarTone}
                avatarSeed={currentUser.avatarSeed}
                avatarStyle={currentUser.avatarStyle}
                avatarIcon={currentUser.avatarIcon}
                size="2xl"
                className="w-24 h-24 sm:w-28 sm:h-28"
              />
            </div>

            {/* Información y Biografía */}
            <div className="flex flex-col gap-1.5 max-w-xl pt-2 sm:pt-4">
              <div className="flex flex-wrap items-center justify-center sm:justify-start gap-2">
                <h1 className="text-2xl sm:text-3xl font-extrabold text-[#231123] dark:text-white tracking-tight">
                  {displayName}
                </h1>
                <span className="px-2.5 py-0.5 rounded-full bg-[#f8e9f6] dark:bg-[#231123] text-[#5c1d5e] dark:text-pink-200 text-xs font-bold border border-[#e6d5e2] dark:border-white/10">
                  {currentUser.role === 'admin' ? t('profile.role_admin', 'Administrador') : t('profile.role_audiophile_pro', 'Audiófilo Pro')}
                </span>

                {equippedTitle && (
                  <span className="px-2.5 py-0.5 rounded-full bg-gradient-to-r from-amber-500 to-[#B80C09] text-white text-xs font-black shadow-xs flex items-center gap-1">
                    <span className="material-symbols-outlined text-[13px]">military_tech</span>
                    <span>{equippedTitle}</span>
                  </span>
                )}

                <span className="px-2.5 py-0.5 rounded-full bg-amber-500/15 text-amber-700 dark:text-amber-300 border border-amber-500/30 text-xs font-mono font-bold flex items-center gap-1">
                  <span className="material-symbols-outlined text-[14px]">toll</span>
                  <span>{userPoints.toLocaleString()} {t('profile.coins', 'Monedas')}</span>
                </span>
              </div>
              <p className="text-sm font-semibold text-[#5c435a] dark:text-[#B89CB0]">
                {handle}
              </p>
              <p className="text-sm sm:text-base text-[#231123]/85 dark:text-gray-200 leading-relaxed mt-1">
                {bio}
              </p>

              {/* Géneros / Gustos Musicales del Usuario */}
              {currentUser.preferences && currentUser.preferences.length > 0 && (
                <div className="flex flex-wrap items-center justify-center sm:justify-start gap-1.5 pt-2">
                  <span className="text-[11px] font-bold text-[#5c435a] dark:text-[#B89CB0] uppercase tracking-wider mr-1">
                    {t('profile.tastes', 'Gustos:')}
                  </span>
                  {currentUser.preferences.map((pref) => (
                    <span
                      key={pref}
                      className="px-2 py-0.5 rounded-md bg-gray-100 dark:bg-[#231123] text-[#231123] dark:text-gray-200 text-xs font-medium border border-[#e6d5e2] dark:border-white/10"
                    >
                      {pref}
                    </span>
                  ))}
                </div>
              )}

              {/* Equipamiento Audiófilo del Usuario */}
              {(() => {
                const setup = currentUser.audiophileSetup || currentUser.gear || {};
                const turntable = setup.turntable;
                const headphones = setup.headphones;
                const dac = setup.dac || setup.amplifier;
                const format = setup.favoriteFormat;

                if (!turntable && !headphones && !dac && !format) return null;

                return (
                  <div className="flex flex-wrap items-center justify-center sm:justify-start gap-1.5 pt-1.5">
                    {turntable && (
                      <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-[#B80C09]/10 text-[#B80C09] dark:text-pink-300 text-[11px] font-bold border border-[#B80C09]/20">
                        <span className="material-symbols-outlined text-[13px]">album</span>
                        <span>{turntable}</span>
                      </span>
                    )}
                    {headphones && (
                      <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-blue-500/10 text-blue-600 dark:text-blue-300 text-[11px] font-bold border border-blue-500/20">
                        <span className="material-symbols-outlined text-[13px]">headphones</span>
                        <span>{headphones}</span>
                      </span>
                    )}
                    {dac && (
                      <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-300 text-[11px] font-bold border border-emerald-500/20">
                        <span className="material-symbols-outlined text-[13px]">speaker</span>
                        <span>{dac}</span>
                      </span>
                    )}
                    {format && (
                      <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-amber-500/10 text-amber-600 dark:text-amber-300 text-[11px] font-bold border border-amber-500/20">
                        <span className="material-symbols-outlined text-[13px]">graphic_eq</span>
                        <span>{format}</span>
                      </span>
                    )}
                  </div>
                );
              })()}
            </div>
          </div>

          {/* Lado Derecho: Estadísticas y Botón de Acción */}
          <div className="flex flex-col items-center md:items-end gap-5 shrink-0 w-full sm:w-auto pt-2 sm:pt-4">
            {/* 3 Estadísticas Sociales */}
            <div className="flex items-center gap-6 sm:gap-8 py-2 px-4 rounded-2xl bg-gray-50 dark:bg-[#231123]/60 border border-[#e6d5e2] dark:border-white/10 shadow-xs">
              <div className="flex flex-col items-center">
                <span className="text-lg sm:text-xl font-extrabold text-[#231123] dark:text-white">
                  {stats.reviews || stats.reviewsCount || 0}
                </span>
                <span className="text-xs text-[#5c435a] dark:text-[#B89CB0] font-medium">
                  {t('profile.reviews_count', 'Reseñas')}
                </span>
              </div>
              <div className="w-[1px] h-8 bg-[#e6d5e2] dark:bg-white/10" />
              <div className="flex flex-col items-center">
                <span className="text-lg sm:text-xl font-extrabold text-[#231123] dark:text-white">
                  {stats.followers || 0}
                </span>
                <span className="text-xs text-[#5c435a] dark:text-[#B89CB0] font-medium">
                  {t('profile.followers', 'Seguidores')}
                </span>
              </div>
              <div className="w-[1px] h-8 bg-[#e6d5e2] dark:bg-white/10" />
              <div className="flex flex-col items-center">
                <span className="text-lg sm:text-xl font-extrabold text-[#231123] dark:text-white">
                  {stats.following ?? 0}
                </span>
                <span className="text-xs text-[#5c435a] dark:text-[#B89CB0] font-medium">
                  {t('profile.following', 'Siguiendo')}
                </span>
              </div>
            </div>

            {/* Botón según sea Perfil Propio o Visitante */}
            {isOwnProfile ? (
              <motion.button
                whileHover={{ scale: 1.03 }}
                whileTap={{ scale: 0.97 }}
                onClick={handleEditClick}
                type="button"
                className="w-full sm:w-auto px-6 py-2.5 rounded-xl border-2 border-[#B80C09] text-[#B80C09] hover:bg-[#B80C09] hover:text-white text-xs sm:text-sm font-bold uppercase tracking-wider transition-all duration-200 cursor-pointer shadow-xs flex items-center justify-center gap-1.5"
              >
                <span className="material-symbols-outlined text-[16px]">tune</span>
                <span>{t('profile.customize_btn', 'Personalizar Perfil & Gustos')}</span>
              </motion.button>
            ) : (
              <motion.button
                whileHover={{ scale: 1.03 }}
                whileTap={{ scale: 0.97 }}
                onClick={handleToggleFollow}
                type="button"
                className={`w-full sm:w-auto px-6 py-2.5 rounded-xl text-xs sm:text-sm font-bold uppercase tracking-wider transition-all duration-200 cursor-pointer shadow-xs flex items-center justify-center gap-1.5 ${
                  isFollowing
                    ? 'bg-gray-200 dark:bg-white/10 text-[#231123] dark:text-white hover:bg-red-500/10 hover:text-red-500'
                    : 'bg-[#B80C09] text-white hover:bg-[#960a07]'
                }`}
              >
                <span className="material-symbols-outlined text-[16px]">
                  {isFollowing ? 'person_remove' : 'person_add'}
                </span>
                <span>{isFollowing ? t('profile.following', 'Siguiendo') : t('profile.follow_btn', 'Seguir Usuario')}</span>
              </motion.button>
            )}
          </div>
        </div>
      </div>
    </motion.section>
  );
};

export default ProfileHeader;

import { useUIText } from '../../../shared/i18n/use-ui-text.js';
