export const RewardsStoreTab = () => {
  const ui = useUIText();
  const { user, updateUser } = useAuth();

  // Balance de Puntos & Pertenencias
  const [points, setPoints] = useState(() => {
    try {
      const saved = localStorage.getItem('sonar_user_points');
      return saved !== null ? Number(saved) : (user?.sonarPoints || 1250);
    } catch {
      return 1250;
    }
  });

  const [userXp, setUserXp] = useState(() => {
    try {
      const saved = localStorage.getItem('sonar_user_xp');
      return saved !== null ? Number(saved) : (user?.audiophileXp || 3450);
    } catch {
      return 3450;
    }
  });

  const [inventory, setInventory] = useState(() => {
    try {
      const saved = localStorage.getItem('sonar_user_inventory');
      return saved ? JSON.parse(saved) : ['frame-gold-vinyl', 'title-absolute-pitch', 'perk-vip-room'];
    } catch {
      return ['frame-gold-vinyl'];
    }
  });

  const [equippedFrame, setEquippedFrame] = useState(() => {
    try {
      return localStorage.getItem('sonar_equipped_frame') || user?.equippedFrame || 'frame-gold-vinyl';
    } catch {
      return 'frame-gold-vinyl';
    }
  });

  const [equippedTitle, setEquippedTitle] = useState(() => {
    try {
      return localStorage.getItem('sonar_equipped_title') || user?.equippedTitle || 'Oído Absoluto';
    } catch {
      return 'Oído Absoluto';
    }
  });

  const [equippedSkin, setEquippedSkin] = useState(() => {
    try {
      return localStorage.getItem('sonar_equipped_skin') || user?.equippedSkin || 'skin-vu-meter';
    } catch {
      return 'skin-vu-meter';
    }
  });

  const [activePerks, setActivePerks] = useState(() => {
    try {
      const saved = localStorage.getItem('sonar_active_perks');
      return saved ? JSON.parse(saved) : (user?.activePerks || ['perk-vip-room']);
    } catch {
      return ['perk-vip-room'];
    }
  });

  // Estado de Caja Sorpresa Diaria
  const [crateOpened, setCrateOpened] = useState(() => {
    try {
      const last = localStorage.getItem('sonar_daily_crate_last_open');
      if (!last) return false;
      const lastDate = new Date(last).toDateString();
      const today = new Date().toDateString();
      return lastDate === today;
    } catch {
      return false;
    }
  });

  const [isOpeningCrate, setIsOpeningCrate] = useState(false);
  const [crateReward, setCrateReward] = useState(null);
  const [activeCategory, setActiveCategory] = useState('all');
  const [toastMessage, setToastMessage] = useState(null);

  // Misiones
  const [quests, setQuests] = useState(() => {
    try {
      const saved = localStorage.getItem('sonar_rewards_quests');
      return saved ? JSON.parse(saved) : INITIAL_QUESTS;
    } catch {
      return INITIAL_QUESTS;
    }
  });

  // Guardar puntos en localStorage y sincronizar con usuario
  const updatePoints = (newPoints) => {
    setPoints(newPoints);
    try {
      localStorage.setItem('sonar_user_points', String(newPoints));
      updateUser?.({ sonarPoints: newPoints });
      window.dispatchEvent(new CustomEvent('sonar:points-updated', { detail: { points: newPoints } }));
      window.dispatchEvent(new CustomEvent('sonar:points-awarded', { detail: { points: newPoints } }));
      window.dispatchEvent(new CustomEvent('sonar:profile-customization-changed', { detail: { sonarPoints: newPoints } }));
    } catch {}
  };

  const updateXp = (newXp) => {
    setUserXp(newXp);
    try {
      localStorage.setItem('sonar_user_xp', String(newXp));
      updateUser?.({ audiophileXp: newXp });
      window.dispatchEvent(new CustomEvent('sonar:profile-customization-changed', { detail: { audiophileXp: newXp } }));
    } catch {}
  };

  // Cálculo de Nivel Audiófilo (1000 XP por nivel)
  const userLevel = Math.max(1, Math.floor(userXp / 300) + 1);
  const currentLevelProgress = (userXp % 300);
  const percentToNextLevel = Math.min(100, Math.round((currentLevelProgress / 300) * 100));

  const showToast = (msg) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3500);
  };

  // Abrir Caja Diaria
  const handleOpenCrate = () => {
    if (crateOpened || isOpeningCrate) return;
    setIsOpeningCrate(true);

    setTimeout(() => {
      const rewardsList = [
        { type: 'points', amount: 150, title: '🎁 +150 Sonar Coins & Racha Dorada' },
        { type: 'points', amount: 250, title: '⭐ ¡Gran Golpe de Suerte! +250 Sonar Coins' },
        { type: 'xp', amount: 300, title: '⚡ +300 XP de Prestigio Acústico' },
        { type: 'both', points: 100, xp: 200, title: '🔥 Pack Combo: +100 Monedas & +200 XP' },
      ];
      const selected = rewardsList[Math.floor(Math.random() * rewardsList.length)];
      
      if (selected.amount) {
        if (selected.type === 'points') updatePoints(points + selected.amount);
        if (selected.type === 'xp') updateXp(userXp + selected.amount);
      } else {
        updatePoints(points + selected.points);
        updateXp(userXp + selected.xp);
      }

      setCrateReward(selected);
      setCrateOpened(true);
      setIsOpeningCrate(false);
      try {
        localStorage.setItem('sonar_daily_crate_last_open', new Date().toISOString());
      } catch {}
      showToast(selected.title);
    }, 1800);
  };

  // Canjear Artículo
  const handleRedeem = (item) => {
    if (inventory.includes(item.id)) return;
    if (points < item.cost) {
      showToast(`❌ Necesitas ${item.cost - points} monedas más para canjear este artículo.`);
      return;
    }

    const nextPoints = points - item.cost;
    const nextInventory = [...inventory, item.id];
    updatePoints(nextPoints);
    setInventory(nextInventory);
    try {
      localStorage.setItem('sonar_user_inventory', JSON.stringify(nextInventory));
    } catch {}

    // Auto-equipar el artículo canjeado
    handleEquip(item);
    showToast(`🎉 ¡Canjeaste con éxito: "${item.name}"! Ya está disponible en tu perfil.`);
  };

  // Equipar Artículo
  const handleEquip = (item) => {
    if (item.type === 'frame') {
      const next = equippedFrame === item.id ? '' : item.id;
      setEquippedFrame(next);
      try {
        localStorage.setItem('sonar_equipped_frame', next);
        updateUser?.({ equippedFrame: next });
        window.dispatchEvent(new CustomEvent('sonar:profile-customization-changed', { detail: { equippedFrame: next } }));
      } catch {}
      showToast(next ? `✨ Marco "${item.name}" equipado` : 'Marco desequipado');
    } else if (item.type === 'title') {
      const cleanTitle = item.name.replace('Título: ', '');
      const next = equippedTitle === cleanTitle ? '' : cleanTitle;
      setEquippedTitle(next);
      try {
        localStorage.setItem('sonar_equipped_title', next);
        updateUser?.({ equippedTitle: next });
        window.dispatchEvent(new CustomEvent('sonar:profile-customization-changed', { detail: { equippedTitle: next } }));
      } catch {}
      showToast(next ? `🎖️ Título "${next}" activado en tu perfil` : 'Título desequipado');
    } else if (item.type === 'skin') {
      const next = equippedSkin === item.id ? '' : item.id;
      setEquippedSkin(next);
      try {
        localStorage.setItem('sonar_equipped_skin', next);
        updateUser?.({ equippedSkin: next });
        window.dispatchEvent(new CustomEvent('sonar:profile-customization-changed', { detail: { equippedSkin: next } }));
      } catch {}
      showToast(next ? `🎛️ Skin "${item.name}" activada en el reproductor` : 'Skin desequipada');
    } else if (item.type === 'perk') {
      const isAlreadyActive = activePerks.includes(item.id);
      const nextPerks = isAlreadyActive
        ? activePerks.filter((id) => id !== item.id)
        : [...activePerks, item.id];
      setActivePerks(nextPerks);
      try {
        localStorage.setItem('sonar_active_perks', JSON.stringify(nextPerks));
        updateUser?.({ activePerks: nextPerks });
        window.dispatchEvent(new CustomEvent('sonar:profile-customization-changed', { detail: { activePerks: nextPerks } }));
      } catch {}
      showToast(!isAlreadyActive ? `🎟️ Pase "${item.name}" activado en tu cuenta` : `Pase "${item.name}" desactivado`);
    }
  };

  // Reclamar Misión
  const handleClaimQuest = (questId) => {
    const q = quests.find((item) => item.id === questId);
    if (!q || q.claimed || q.progress < q.target) return;

    const updated = quests.map((item) => (item.id === questId ? { ...item, claimed: true } : item));
    setQuests(updated);
    updatePoints(points + q.rewardPts);
    updateXp(userXp + q.rewardPts * 2);

    try {
      localStorage.setItem('sonar_rewards_quests', JSON.stringify(updated));
    } catch {}

    showToast(`🎁 ¡Reclamaste +${q.rewardPts} Sonar Coins y +${q.rewardPts * 2} XP!`);
  };

  const filteredItems = REWARD_ITEMS.filter((item) => {
    if (activeCategory === 'all') return true;
    if (activeCategory === 'frames') return item.type === 'frame';
    if (activeCategory === 'skins') return item.type === 'skin';
    if (activeCategory === 'titles') return item.type === 'title';
    if (activeCategory === 'perks') return item.type === 'perk';
    return true;
  });

  return (
    <div className="flex flex-col gap-8 text-[#231123] dark:text-white">
      {/* Toast Notificación */}
      <AnimatePresence>
        {toastMessage && (
          <motion.div
            initial={{ opacity: 0, y: -20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -20, scale: 0.95 }}
            className="fixed top-20 right-6 z-50 px-4 py-3 rounded-2xl bg-[#231123]/95 text-white dark:bg-white dark:text-[#231123] font-bold text-xs shadow-2xl border border-amber-400/40 flex items-center gap-2 backdrop-blur-xl"
          >
            <span className="material-symbols-outlined text-amber-400 text-[18px]">verified</span>
            <span>{toastMessage}</span>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 1. TARJETA PRINCIPAL: BALANCE DE MONEDAS, NIVEL XP & RACHA */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
        {/* Saldo de Sonar Coins */}
        <div className="p-6 sm:p-7 rounded-3xl bg-gradient-to-br from-[#003844] via-[#003844] to-[#231123] text-[#DCDCDD] shadow-xl flex flex-col justify-between gap-4 relative overflow-hidden border border-[#003844]/40">
          <div className="absolute top-0 right-0 -mt-4 -mr-4 w-32 h-32 rounded-full bg-white/5 blur-xl pointer-events-none" />
          <div className="flex items-center justify-between">
            <span className="text-xs font-black uppercase tracking-wider text-[#DCDCDD] flex items-center gap-1.5">
              <span className="material-symbols-outlined text-[18px] text-[#52a2b0]">toll</span>
              <span>{ui("Saldo Sonar Coins")}</span>
            </span>
            <span className="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-[#231123]/60 backdrop-blur-md text-[#DCDCDD] border border-white/20">{ui("Boutique Activa")}</span>
          </div>

          <div className="flex items-baseline gap-3 my-1">
            <span className="text-4xl sm:text-5xl font-black tracking-tight font-mono text-white">
              {points.toLocaleString()}
            </span>
            <span className="text-xs font-bold text-[#DCDCDD]/80 uppercase tracking-widest">{ui("Monedas")}</span>
          </div>

          <p className="text-xs text-[#DCDCDD]/80 leading-relaxed">{ui("Acumula monedas escuchando pistas en alta resolución, redactando reseñas y manteniendo tu racha de escucha.")}</p>
        </div>

        {/* Nivel Audiófilo & Barra de XP */}
        <div className="p-6 sm:p-7 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-xs flex flex-col justify-between gap-4">
          <div className="flex items-center justify-between">
            <span className="text-xs font-black uppercase tracking-wider text-[#B80C09] dark:text-[#ff4d4a] flex items-center gap-1.5">
              <span className="material-symbols-outlined text-[18px]">military_tech</span>
              <span>{ui("Rango & Experiencia")}</span>
            </span>
            <span className="text-xs font-mono font-extrabold text-[#5c435a] dark:text-[#DCDCDD]">
              {userXp.toLocaleString()} XP
            </span>
          </div>

          <div>
            <div className="flex items-baseline justify-between mb-1.5">
              <h3 className="text-xl sm:text-2xl font-black text-[#231123] dark:text-[#DCDCDD]">{ui("Nivel")} {userLevel} · <span className="text-sm text-[#5c435a] dark:text-[#B89CB0]">{equippedTitle}</span>
              </h3>
              <span className="text-xs font-mono font-bold text-[#B80C09] dark:text-[#ff4d4a]">
                {percentToNextLevel}%
              </span>
            </div>

            <div className="w-full h-3 bg-gray-100 dark:bg-black/40 rounded-full overflow-hidden p-0.5 border border-[#e6d5e2] dark:border-white/10">
              <motion.div
                initial={{ width: 0 }}
                animate={{ width: `${percentToNextLevel}%` }}
                className="h-full rounded-full bg-gradient-to-r from-[#003844] via-[#4B2840] to-[#B80C09]"
              />
            </div>
          </div>

          <span className="text-[11px] text-[#5c435a] dark:text-[#B89CB0] font-medium">{ui("Faltan")} {300 - currentLevelProgress} {ui("XP para alcanzar el")} <strong>{ui("Nivel")} {userLevel + 1}</strong>
          </span>
        </div>

        {/* Racha de Días & Caja Sorpresa Diaria */}
        <div className="p-6 sm:p-7 rounded-3xl bg-gradient-to-br from-[#4B2840] to-[#231123] text-[#DCDCDD] border border-white/15 shadow-xl flex flex-col justify-between gap-4">
          <div className="flex items-center justify-between">
            <span className="text-xs font-black uppercase tracking-wider text-[#DCDCDD] flex items-center gap-1.5">
              <span className="material-symbols-outlined text-[18px] text-[#B80C09]">local_fire_department</span>
              <span>{ui("Racha de Escucha")}</span>
            </span>
            <span className="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-[#003844]/60 text-[#DCDCDD] border border-[#003844]/80">{ui("🔥 5 Días Seguidos")}</span>
          </div>

          {/* Botón de Caja Diaria */}
          <div className="p-4 rounded-2xl bg-black/40 border border-white/10 flex items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-[#003844] to-[#B80C09] text-white flex items-center justify-center shadow-md shrink-0">
                <span className="material-symbols-outlined text-[22px]">
                  {crateOpened ? 'lock_open' : 'redeem'}
                </span>
              </div>
              <div>
                <span className="text-xs font-extrabold block text-white">
                  {crateOpened ? ui("Caja Diaria Reclamada") : ui("Caja Sorpresa Diaria")}
                </span>
                <span className="text-[10px] text-[#B89CB0]">
                  {crateOpened ? ui("Vuelve mañana para más premios") : ui("Gira y gana monedas y XP")}
                </span>
              </div>
            </div>

            <button
              type="button"
              onClick={handleOpenCrate}
              disabled={crateOpened || isOpeningCrate}
              className={`px-3.5 py-2 rounded-xl text-xs font-black uppercase tracking-wider transition-all cursor-pointer shadow-md ${
                crateOpened
                  ? 'bg-white/10 text-white/40 cursor-not-allowed'
                  : isOpeningCrate
                  ? 'bg-[#003844] text-white animate-pulse'
                  : 'bg-gradient-to-r from-[#003844] to-[#B80C09] hover:from-[#002830] hover:to-[#9c0a07] text-white hover:scale-105'
              }`}
            >
              {crateOpened ? ui("✓ Abierta") : isOpeningCrate ? ui("Abriendo...") : ui("Abrir Gratis")}
            </button>
          </div>

          <div className="flex items-center justify-between text-[11px] text-[#B89CB0]">
            <span>{ui("Multiplicador de puntos:")}</span>
            <span className="font-mono font-bold text-[#DCDCDD]">{ui("1.5x Bonificación Activa")}</span>
          </div>
        </div>
      </div>

      {/* 2. BOUTIQUE DE CANJE (STORE DE MARCOS, SKINS Y TÍTULOS) */}
      <div className="p-6 sm:p-8 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-xs flex flex-col gap-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-[#e6d5e2] dark:border-white/10">
          <div>
            <span className="text-xs font-extrabold uppercase tracking-wider text-[#B80C09] flex items-center gap-1.5">
              <span className="material-symbols-outlined text-[16px]">storefront</span>
              <span>{ui("Boutique Exclusiva Sonar Hi-Fi")}</span>
            </span>
            <h3 className="text-xl sm:text-2xl font-black text-[#231123] dark:text-white mt-1">{ui("Catálogo de Canje & Personalización")}</h3>
            <p className="text-xs text-[#5c435a] dark:text-[#B89CB0] mt-0.5">{ui("Personaliza tu avatar, desbloquea skins visuales para el reproductor y luce títulos de prestigio.")}</p>
          </div>

          {/* Selector de Categorías */}
          <div className="flex items-center gap-1.5 overflow-x-auto pb-1 self-start sm:self-auto">
            {[
              { id: 'all', label: 'Todos' },
              { id: 'frames', label: '👑 Marcos' },
              { id: 'skins', label: '🎛️ Skins Audio' },
              { id: 'titles', label: '🎖️ Títulos' },
              { id: 'perks', label: '🎟️ Pases' },
            ].map((cat) => (
              <button
                key={cat.id}
                type="button"
                onClick={() => setActiveCategory(cat.id)}
                className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer whitespace-nowrap ${
                  activeCategory === cat.id
                    ? 'bg-[#B80C09] text-white shadow-xs'
                    : 'bg-gray-100 dark:bg-white/5 text-[#5c435a] dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/10'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </div>

        {/* Grid de Artículos */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
          {filteredItems.map((item) => {
            const isOwned = inventory.includes(item.id);
            const isEquipped =
              (item.type === 'frame' && equippedFrame === item.id) ||
              (item.type === 'title' && equippedTitle === item.name.replace('Título: ', '')) ||
              (item.type === 'skin' && equippedSkin === item.id) ||
              (item.type === 'perk' && activePerks.includes(item.id));

            return (
              <motion.div
                key={item.id}
                whileHover={{ y: -4 }}
                className={`p-5 rounded-2xl border transition-all flex flex-col justify-between gap-4 ${
                  isEquipped
                    ? 'bg-[#003844]/10 dark:bg-[#003844]/30 border-[#003844] dark:border-[#52a2b0] shadow-md ring-2 ring-[#003844]/40'
                    : isOwned
                    ? 'bg-[#4B2840]/10 dark:bg-[#4B2840]/25 border-[#4B2840]/30 dark:border-white/15'
                    : 'bg-gray-50/60 dark:bg-black/20 border-gray-200 dark:border-white/10 hover:border-[#003844]/50'
                }`}
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div
                      className={`w-12 h-12 rounded-2xl bg-gradient-to-tr ${item.color} text-white flex items-center justify-center shadow-md shrink-0 overflow-hidden`}
                    >
                      <span className="material-symbols-outlined text-[24px] select-none pointer-events-none">{item.icon}</span>
                    </div>
                    <div>
                      <h4 className="text-sm font-extrabold text-[#231123] dark:text-[#DCDCDD] flex items-center gap-1.5">
                        <span>{item.name}</span>
                        {item.badge && (
                          <span className="px-1.5 py-0.2 rounded text-[9px] font-black uppercase bg-[#B80C09] text-white">
                            {item.badge}
                          </span>
                        )}
                      </h4>
                      <span className="text-[11px] font-bold text-[#5c435a] dark:text-[#B89CB0]">
                        {item.category}
                      </span>
                    </div>
                  </div>
                </div>

                <p className="text-xs text-[#5c435a] dark:text-[#B89CB0] leading-relaxed">
                  {item.description}
                </p>

                {/* Previsualizador de Marco si aplica */}
                {item.type === 'frame' && (
                  <div className="p-3 rounded-xl bg-white dark:bg-black/30 border border-[#e6d5e2] dark:border-white/10 flex items-center gap-3">
                    <div className={`w-9 h-9 rounded-full bg-gradient-to-tr ${item.color} flex items-center justify-center text-white ${item.previewBorder}`}>
                      <span className="material-symbols-outlined text-[16px]">person</span>
                    </div>
                    <span className="text-[11px] font-bold text-[#5c435a] dark:text-[#DCDCDD]">{ui("Vista previa en avatar")}</span>
                  </div>
                )}

                {/* Botón de Acción: Canjear o Equipar */}
                <div className="pt-3 border-t border-[#e6d5e2] dark:border-white/10 flex items-center justify-between gap-3">
                  <div className="flex items-center gap-1 font-mono font-extrabold text-sm text-[#231123] dark:text-[#DCDCDD]">
                    <span className="material-symbols-outlined text-[#003844] dark:text-[#52a2b0] text-[18px]">toll</span>
                    <span>{isOwned ? (item.type === 'perk' ? ui("Pase Activo") : ui("Adquirido")) : `${item.cost} Monedas`}</span>
                  </div>

                  {isOwned ? (
                    <button
                      type="button"
                      onClick={() => handleEquip(item)}
                      className={`px-3.5 py-1.5 rounded-xl text-xs font-extrabold transition-all cursor-pointer flex items-center gap-1 shadow-xs ${
                        isEquipped
                          ? 'bg-[#003844] hover:bg-[#002830] text-[#DCDCDD] shadow-[#003844]/30'
                          : 'bg-gray-200 dark:bg-white/10 hover:bg-[#B80C09] hover:text-white text-[#231123] dark:text-[#DCDCDD]'
                      }`}
                    >
                      <span className="material-symbols-outlined text-[15px]">
                        {isEquipped ? 'check_circle' : item.type === 'perk' ? 'vpn_key' : 'tune'}
                      </span>
                      <span>{isEquipped ? (item.type === 'perk' ? ui("Activo") : ui("Equipado")) : (item.type === 'perk' ? ui("Activar") : ui("Equipar"))}</span>
                    </button>
                  ) : (
                    <button
                      type="button"
                      onClick={() => handleRedeem(item)}
                      disabled={points < item.cost}
                      className={`px-3.5 py-1.5 rounded-xl text-xs font-black uppercase tracking-wider transition-all cursor-pointer shadow-md flex items-center gap-1 ${
                        points >= item.cost
                          ? 'bg-gradient-to-r from-[#003844] to-[#B80C09] hover:from-[#002830] hover:to-[#9c0a07] text-white hover:scale-105'
                          : 'bg-gray-200 dark:bg-white/10 text-gray-400 dark:text-gray-500 cursor-not-allowed'
                      }`}
                    >
                      <span className="material-symbols-outlined text-[15px]">shopping_cart</span>
                      <span>{ui("Canjear")}</span>
                    </button>
                  )}
                </div>
              </motion.div>
            );
          })}
        </div>
      </div>

      {/* 3. MISIONES DINÁMICAS & DESAFÍOS DE ESCUCHA */}
      <div className="p-6 sm:p-8 rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10 shadow-xs flex flex-col gap-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div>
            <span className="text-xs font-bold uppercase tracking-wider text-[#B80C09] flex items-center gap-1.5">
              <span className="material-symbols-outlined text-[16px]">task_alt</span>
              <span>{ui("Desafíos & Misiones Semanales")}</span>
            </span>
            <h3 className="text-xl sm:text-2xl font-black text-[#231123] dark:text-white mt-1">{ui("Gana Monedas Cumpliendo Metas Musicales")}</h3>
            <p className="text-xs text-[#5c435a] dark:text-[#B89CB0] mt-0.5">{ui("Completa cada objetivo para reclamar monedas y sumar puntos de experiencia inmediatamente.")}</p>
          </div>

          <span className="text-xs font-mono font-bold text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-950/60 px-3.5 py-1.5 rounded-xl border border-amber-300/40 self-start sm:self-auto shadow-2xs">{ui("Renuevan cada lunes")}</span>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {quests.map((quest) => {
            const isDone = quest.progress >= quest.target;
            const percent = Math.min(100, Math.round((quest.progress / quest.target) * 100));

            return (
              <div
                key={quest.id}
                className={`p-5 rounded-2xl border transition-all flex flex-col justify-between gap-4 ${
                  quest.claimed
                    ? 'bg-emerald-50/30 dark:bg-emerald-950/20 border-emerald-300 dark:border-emerald-500/30'
                    : isDone
                    ? 'bg-amber-50/50 dark:bg-amber-950/30 border-amber-300 dark:border-amber-500/40 shadow-xs'
                    : 'bg-gray-50/70 dark:bg-black/20 border-gray-200 dark:border-white/10'
                }`}
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div
                      className={`w-11 h-11 rounded-2xl flex items-center justify-center shrink-0 ${
                        quest.claimed
                          ? 'bg-emerald-600 text-white'
                          : isDone
                          ? 'bg-gradient-to-tr from-amber-500 to-[#B80C09] text-white shadow-md'
                          : 'bg-gray-200 dark:bg-white/10 text-gray-400 dark:text-white/40'
                      }`}
                    >
                      <span className="material-symbols-outlined text-[22px]">{quest.icon}</span>
                    </div>
                    <div>
                      <h4 className="text-sm font-bold text-[#231123] dark:text-white">
                        {quest.title}
                      </h4>
                      <p className="text-xs text-[#5c435a] dark:text-[#B89CB0] mt-0.5">
                        {quest.desc}
                      </p>
                    </div>
                  </div>
                </div>

                <div className="flex flex-col gap-1.5">
                  <div className="flex justify-between text-[11px] font-bold">
                    <span className="text-[#5c435a] dark:text-[#B89CB0]">{ui("Progreso:")} {quest.progress} / {quest.target}
                    </span>
                    <span className="font-mono text-[#B80C09] dark:text-pink-300">{percent}%</span>
                  </div>
                  <div className="w-full h-2 bg-gray-200 dark:bg-black/30 rounded-full overflow-hidden p-0.5">
                    <motion.div
                      initial={{ width: 0 }}
                      animate={{ width: `${percent}%` }}
                      className="h-full rounded-full bg-gradient-to-r from-[#B80C09] to-amber-500"
                    />
                  </div>
                </div>

                <div className="pt-2 border-t border-[#e6d5e2] dark:border-white/10 flex items-center justify-between">
                  <span className="text-xs font-mono font-bold text-amber-600 dark:text-amber-400 flex items-center gap-1">
                    <span className="material-symbols-outlined text-[16px]">toll</span>
                    <span>+{quest.rewardPts} {ui("Monedas")}</span>
                  </span>

                  {quest.claimed ? (
                    <span className="text-xs font-black uppercase text-emerald-600 dark:text-emerald-400 flex items-center gap-1">
                      <span className="material-symbols-outlined text-[16px]">verified</span>
                      <span>{ui("Reclamado")}</span>
                    </span>
                  ) : isDone ? (
                    <button
                      type="button"
                      onClick={() => handleClaimQuest(quest.id)}
                      className="px-3 py-1.5 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-700 hover:from-emerald-500 hover:to-teal-600 text-white font-extrabold text-xs cursor-pointer shadow-md flex items-center gap-1"
                    >
                      <span className="material-symbols-outlined text-[15px]">redeem</span>
                      <span>{ui("Reclamar Recompensa")}</span>
                    </button>
                  ) : (
                    <span className="text-xs text-gray-400 dark:text-gray-500 font-semibold">{ui("En curso")}</span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default RewardsStoreTab;

import { useUIText } from '../../../shared/i18n/use-ui-text.js';
import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { DEFAULT_FALLBACK_COVER, handleImageFallbackError } from '../../../shared/services/recommendations-service';

export const VinylCrateFlip = ({ albums = [], onPlayAlbum, onToggleSave }) => {
  const ui = useUIText();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [goldmineGrades, setGoldmineGrades] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem('sonar_goldmine_grades') || '{}');
    } catch {
      return {};
    }
  });

  const currentAlbum = albums[currentIndex] || null;

  const handlePrev = () => {
    setIsFlipped(false);
    setCurrentIndex((prev) => (prev > 0 ? prev - 1 : albums.length - 1));
  };

  const handleNext = () => {
    setIsFlipped(false);
    setCurrentIndex((prev) => (prev < albums.length - 1 ? prev + 1 : 0));
  };

  const handleSetGrade = (albumId, grade) => {
    const updated = { ...goldmineGrades, [albumId]: grade };
    setGoldmineGrades(updated);
    try {
      localStorage.setItem('sonar_goldmine_grades', JSON.stringify(updated));
    } catch {}
  };

  if (!albums || albums.length === 0) {
    return (
      <div className="p-12 text-center rounded-3xl bg-white dark:bg-[#4B2840] border border-[#e6d5e2] dark:border-white/10">
        <span className="material-symbols-outlined text-[48px] text-[#5c435a] dark:text-[#B89CB0]">album</span>
        <h4 className="text-lg font-bold text-[#231123] dark:text-white mt-3">{ui("Tu Caja de Vinilos está vacía")}</h4>
        <p className="text-xs text-[#5c435a] dark:text-[#B89CB0] mt-1">{ui("Guarda álbumes en tu colección para hojearlos en el visor 3D.")}</p>
      </div>
    );
  }

  const currentGrade = currentAlbum ? goldmineGrades[currentAlbum.id] || 'Near Mint (NM)' : 'NM';

  return (
    <div className="w-full flex flex-col items-center gap-6 p-6 sm:p-8 rounded-3xl bg-gradient-to-b from-[#231123]/90 via-[#33182b] to-[#231123] text-white border border-white/15 shadow-2xl relative overflow-hidden select-none">
      {/* Luz ambiental superior estilo tienda de vinilos */}
      <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-transparent via-[#B80C09] to-transparent" />
      <div className="absolute top-2 right-4 text-[11px] font-mono text-pink-200/60 uppercase tracking-widest flex items-center gap-1.5">
        <span className="material-symbols-outlined text-[14px] text-[#B80C09]">3d_rotation</span>
        <span>{ui("Modo Caja 3D •")} {currentIndex + 1} {ui("de")} {albums.length}</span>
      </div>

      {/* Contenedor 3D de la Carátula y el Disco */}
      <div className="w-full max-w-md h-72 sm:h-80 flex items-center justify-center relative perspective-[1200px] mt-4">
        {/* Vinilo saliendo por el lateral derecho */}
        <motion.div
          animate={{
            x: isFlipped ? 60 : 35,
            rotate: isFlipped ? 180 : currentIndex * 45,
          }}
          transition={{ type: 'spring', stiffness: 200, damping: 25 }}
          className="absolute w-56 h-56 sm:w-64 sm:h-64 rounded-full bg-black border-4 border-gray-900 shadow-[0_10px_30px_rgba(0,0,0,0.8)] flex items-center justify-center z-0 cursor-pointer"
          onClick={() => onPlayAlbum && onPlayAlbum(currentAlbum)}
          title={ui("Haz clic para reproducir este vinilo")}
        >
          {/* Surcos del vinilo */}
          <div className="w-full h-full rounded-full border border-white/10 flex items-center justify-center p-6">
            <div className="w-full h-full rounded-full border border-white/5 flex items-center justify-center p-6">
              <div className="w-full h-full rounded-full border border-white/10 flex items-center justify-center p-6">
                {/* Galleta central */}
                <div className="w-20 h-20 rounded-full bg-[#B80C09] border-2 border-white/30 flex items-center justify-center text-center p-2 overflow-hidden shadow-inner">
                  <span className="text-[9px] font-black uppercase text-white leading-tight truncate">
                    {currentAlbum?.artist || 'SONAR'}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </motion.div>

        {/* Portada física del álbum con efecto de grosor e inclinación */}
        <AnimatePresence mode="wait">
          <motion.div
            key={currentAlbum?.id || currentIndex}
            initial={{ opacity: 0, rotateY: -35, scale: 0.9, x: -30 }}
            animate={{ opacity: 1, rotateY: isFlipped ? 180 : -10, scale: 1, x: 0 }}
            exit={{ opacity: 0, rotateY: 35, scale: 0.9, x: 30 }}
            transition={{ type: 'spring', stiffness: 250, damping: 24 }}
            className="w-56 h-56 sm:w-64 sm:h-64 rounded-2xl relative shadow-[0_20px_40px_rgba(0,0,0,0.7)] z-10 cursor-pointer preserve-3d"
            onClick={() => setIsFlipped(!isFlipped)}
          >
            {/* Cara frontal */}
            <div className="absolute inset-0 rounded-2xl overflow-hidden border border-white/20 backface-hidden bg-[#4B2840]">
              <img
                src={currentAlbum?.cover || DEFAULT_FALLBACK_COVER}
                alt={currentAlbum?.title || 'Vinilo'}
                onError={(e) => handleImageFallbackError(e, currentAlbum?.title || 'Album')}
                className="w-full h-full object-cover"
              />
              {/* Reflejo plástico vintage */}
              <div className="absolute inset-0 bg-gradient-to-tr from-black/40 via-transparent to-white/15 pointer-events-none" />
              <div className="absolute top-2 left-2 px-2 py-0.5 rounded-md bg-black/70 backdrop-blur-md text-[10px] font-mono font-bold text-amber-300 border border-white/10">
                180g HI-RES
              </div>
            </div>
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Información del Álbum Actual */}
      <div className="flex flex-col items-center text-center gap-1.5 z-10 max-w-md w-full">
        <h3 className="text-xl sm:text-2xl font-black text-white tracking-tight truncate w-full">
          {currentAlbum?.title || ui("Título del Álbum")}
        </h3>
        <p className="text-sm font-semibold text-pink-200/80">
          {currentAlbum?.artist || ui("Artista")} • {currentAlbum?.year || ui("Edición Maestra")}
        </p>

        {/* Selector de Estado Físico Goldmine */}
        <div className="flex items-center gap-2 mt-2">
          <span className="text-[11px] text-white/70 font-medium">{ui("Estado Físico:")}</span>
          <select
            value={currentGrade}
            onChange={(e) => handleSetGrade(currentAlbum.id, e.target.value)}
            className="text-xs font-bold py-1 px-2.5 rounded-lg bg-white/10 hover:bg-white/20 border border-white/20 text-white focus:outline-hidden focus:border-[#B80C09] cursor-pointer"
          >
            <option value="Mint (M)" className="bg-[#231123] text-white">{ui("Mint (M) - Impecable")}</option>
            <option value="Near Mint (NM)" className="bg-[#231123] text-white">{ui("Near Mint (NM) - Casi Nuevo")}</option>
            <option value="Very Good Plus (VG+)" className="bg-[#231123] text-white">Very Good Plus (VG+)</option>
            <option value="Very Good (VG)" className="bg-[#231123] text-white">{ui("Very Good (VG) - Buen Estado")}</option>
            <option value="Good (G)" className="bg-[#231123] text-white">{ui("Good (G) - Con Desgaste")}</option>
          </select>
        </div>
      </div>

      {/* Controles de Navegación & Reproducción */}
      <div className="flex items-center gap-4 z-10">
        <button
          type="button"
          onClick={handlePrev}
          className="p-3 rounded-2xl bg-white/10 hover:bg-white/20 text-white transition-all border border-white/15 flex items-center justify-center cursor-pointer shadow-md hover:scale-105"
          title={ui("Vinilo anterior")}
        >
          <span className="material-symbols-outlined text-[22px]">arrow_back</span>
        </button>

        <button
          type="button"
          onClick={() => onPlayAlbum && onPlayAlbum(currentAlbum)}
          className="px-6 py-3 rounded-2xl bg-[#B80C09] hover:bg-[#960a07] text-white text-xs font-black tracking-wider uppercase transition-all shadow-[0_0_20px_rgba(184,12,9,0.5)] flex items-center gap-2 cursor-pointer hover:scale-105"
        >
          <span className="material-symbols-outlined text-[20px]">play_arrow</span>
          <span>{ui("Poner en Tornamesa")}</span>
        </button>

        <button
          type="button"
          onClick={handleNext}
          className="p-3 rounded-2xl bg-white/10 hover:bg-white/20 text-white transition-all border border-white/15 flex items-center justify-center cursor-pointer shadow-md hover:scale-105"
          title={ui("Siguiente vinilo")}
        >
          <span className="material-symbols-outlined text-[22px]">arrow_forward</span>
        </button>
      </div>
    </div>
  );
};

export default VinylCrateFlip;

import { useUIText } from '../../../shared/i18n/use-ui-text.js';
﻿import { useState } from 'react'
import { useAuth } from '../../../shared/context/auth-context.jsx'
import { submitCommunityReport } from '../../../shared/services/report-service.js'
export function ReportReview({ review }) {
  const ui = useUIText();
  const { user } = useAuth()
  const [open, setOpen] = useState(false)
  const [reason, setReason] = useState('')
  const [busy, setBusy] = useState(false)
  const [message, setMessage] = useState('')
  if (!review.userId) return null
  async function submit(event) {
    event.preventDefault()
    if (!user) { window.location.hash = '#login'; return }
    if (busy || !reason.trim()) return
    setBusy(true)
    try {
      await submitCommunityReport({ authorId: review.userId, reporter: user, contentType: 'review', contentId: review.id, contentSnapshot: review.content, reason })
      setMessage('Reporte enviado para revisión.'); setOpen(false); setReason('')
    } catch (error) { setMessage(error.message) } finally { setBusy(false) }
  }
  return <div><button type="button" onClick={() => setOpen(!open)}>{ui("Reportar reseña")}</button>{open && <form onSubmit={submit} className="admin-form"><label>{ui("Motivo del reporte")}<textarea required maxLength={1000} value={reason} onChange={e => setReason(e.target.value)} /></label><button disabled={busy}>{busy ? ui("Enviando…") : ui("Enviar reporte")}</button><button type="button" onClick={() => setOpen(false)}>{ui("Cancelar")}</button></form>}{message && <p role="status">{message}</p>}</div>
}

