];

export const ReviewsFeedPage = () => {
  const ui = useUIText();
  const { playTrack, toggleTrack, currentTrack, isPlaying, openReviewModal } = usePlayer();
  const { user } = useAuth() || {};
  const [selectedGenre, setSelectedGenre] = useState('Todos');
